!important}.leaflet-control-zoom a{border:1px solid #dce7eb!important;margin-bottom:3px;border-radius:8px!important}.legend{display:flex;gap:.4rem;align-items:center;font-size:.7rem;color:#71808d;margin-top:.35rem}@media(max-width:900px){.map-page{left:0!important;right:0}.map-panel{width:250px}.map-status{left:8px;right:8px;bottom:8px}}@media(max-width:600px){.map-panel{top:8px;right:8px;width:220px}.map-tools{top:8px;left:8px}.map-status .optional{display:none}}
