btn-sm w-100" id="analysisToggle"><i class="fa-solid fa-magnifying-glass-location me-1"></i>{{ __('Simple Analysis') }}</button><div class="analysis" id="analysisBox"><div class="mt-2"><label class="form-label">{{ __('Analysis') }}</label><select id="analysisType" class="form-select form-select-sm"><option value="radius_search">{{ __('Nearby containers & dumpsites') }}</option><option value="nearest_dumpsite">{{ __('Nearest active dumpsite') }}</option></select></div><div id="radiusWrap" class="mt-2"><label class="form-label">{{ __('Radius (km)') }}</label><input id="radius" type="number" class="form-control form-control-sm" value="0.5" min="0.1" max="10" step="0.1"></div><div class="small text-muted mt-2">{{ __('Choose an analysis, then click any location on the map.') }}</div><div id="analysisResult"></div></div></div><div class="panel-section d-flex gap-2"><button class="btn btn-outline-secondary btn-sm flex-fill" id="exportBtn"><i class="fa-solid fa-download me-1"></i>{{ __('Export') }}</button><button class="btn btn-outline-secondary btn-sm flex-fill" id="refreshBtn"><i class="fa-solid fa-rotate me-1"></i>{{ __('Refresh') }}</button></div></div>
