@push('scripts')<script>
const map=L.map('map',{center:[DEFAULT_LAT,DEFAULT_LNG],zoom:DEFAULT_ZOOM,zoomControl:false});
const tiles={osm:L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap',maxZoom:19}),satellite:L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'© Esri',maxZoom:19}),topo:L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',{attribution:'© OpenTopoMap',maxZoom:17})};tiles.osm.addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);
const groups={containers:L.layerGroup().addTo(map),vehicles:L.layerGroup().addTo(map),dumpsites:L.layerGroup().addTo(map),complaints:L.layerGroup().addTo(map)};let heatLayer=null,clusterOn=false,raw={containers:[],vehicles:[],dumpsites:[],complaints:[]};
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function popup(title,rows){return `<div class="map-popup"><h6>${esc(title)}</h6>${rows.map(r=>`<div class="popup-line"><span>${esc(r[0])}</span><b>${esc(r[1])}</b></div>`).join('')}</div>`}
function containerMarker(f){const p=f.properties||{},fill=Number(p.fill_level||0),color=fill>=80?'#d94b55':fill>=50?'#d88919':'#35b69b';return L.circleMarker([f.geometry.coordinates[1],f.geometry.coordinates[0]],{radius:8,fillColor:color,color:'#fff',weight:2,fillOpacity:.9}).bindPopup(popup(p.name||p.code||'Container',[['Code',p.code],['Fill',`${Math.round(fill)}%`],['Zone',p.zone||'-'],['Status',p.status||'-']]))}
function pointMarker(f,type){const p=f.properties||{},colors={vehicles:'#7a55a6',dumpsites:'#d88919',complaints:'#d94b55'},icons={vehicles:'fa-truck',dumpsites:'fa-warehouse',complaints:'fa-message-exclamation'},color=colors[type];return L.marker([f.geometry.coordinates[1],f.geometry.coordinates[0]],{icon:L.divIcon({className:'',html:`<div style="width:30px;height:30px;border-radius:9px;background:${color};color:#fff;border:2px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.25);display:grid;place-items:center;font-size:11px"><i class="fa-solid ${icons[type]}"></i></div>`,iconSize:[30,30],iconAnchor:[15,15]})}).bindPopup(popup(p.name||p.plate_number||p.ticket||type,[['Status',p.status||'-'],['Type',p.type||p.category||'-'],['Driver',p.driver||'-'],['Priority',p.priority||'-']]))}
function draw(){Object.values(groups).forEach(g=>g.clearLayers());let count=0,filter=Number(document.getElementById('fillFilter').value);raw.containers.filter(f=>Number(f.properties?.fill_level||0)>=filter).forEach(f=>{groups.containers.addLayer(containerMarker(f));count++});raw.vehicles.forEach(f=>{groups.vehicles.addLayer(pointMarker(f,'vehicles'));count++});raw.dumpsites.forEach(f=>{groups.dumpsites.addLayer(pointMarker(f,'dumpsites'));count++});raw.complaints.forEach(f=>{groups.complaints.addLayer(pointMarker(f,'complaints'));count++});document.getElementById('featureCount').textContent=count;document.getElementById('statusText').textContent=`${count} {{ __('features visible') }}`}
async function load(){document.getElementById('statusText').textContent='{{ __('Loading layers…') }}';try{const r=await fetch('{{ route('map.layers.all') }}');const d=await r.json();raw.containers=d.containers?.features||[];raw.vehicles=d.vehicles?.features||[];raw.dumpsites=d.dumpsites?.features||[];raw.complaints=d.complaints?.features||[];document.getElementById('containersCount').textContent=raw.containers.length;document.getElementById('vehiclesCount').textContent=raw.vehicles.length;document.getElementById('dumpsitesCount').textContent=raw.dumpsites.length;draw();if(heatLayer)heatLayer.remove();heatLayer=L.heatLayer((d.heatmap||[]).map(x=>[x[0],x[1],x[2]||.5]),{radius:24,blur:18,maxZoom:17});}catch(e){console.error(e);document.getElementById('statusText').textContent='{{ __('Could not load map data') }}'}}
['containers','vehicles','dumpsites','complaints'].forEach(id=>document.getElementById(id).addEventListener('change',e=>{const g=groups[id];if(e.target.checked)g.addTo(map);else g.remove()}));document.getElementById('fillFilter').addEventListener('input',e=>{document.getElementById('fillValue').textContent=e.target.value;draw()});document.getElementById('baseMap').addEventListener('change',e=>{Object.values(tiles).forEach(t=>map.removeLayer(t));tiles[e.target.value].addTo(map)});document.getElementById('zoomIn').onclick=()=>map.zoomIn();document.getElementById('zoomOut').onclick=()=>map.zoomOut();document.getElementById('locate').onclick=()=>map.setView([DEFAULT_LAT,DEFAULT_LNG],DEFAULT_ZOOM);document.getElementById('full').onclick=()=>document.querySelector('.map-page').requestFullscreen?.();document.getElementById('heat').onclick=e=>{if(!heatLayer)return;if(map.hasLayer(heatLayer)){heatLayer.remove();e.currentTarget.classList.remove('active')}else{heatLayer.addTo(map);e.currentTarget.classList.add('active')}};document.getElementById('cluster').onclick=e=>{clusterOn=!clusterOn;e.currentTarget.classList.toggle('active',clusterOn);if(clusterOn){const cluster=L.markerClusterGroup();['vehicles','dumpsites','complaints'].forEach(k=>groups[k].eachLayer(x=>cluster.addLayer(x)));map.addLayer(cluster);e.currentTarget.dataset.cluster='1'}else{document.querySelectorAll('.leaflet-marker-icon').forEach(()=>{});draw();['vehicles','dumpsites','complaints'].forEach(k=>document.getElementById(k).checked&&groups[k].addTo(map))}};
document.getElementById('refreshBtn').onclick=load;document.getElementById('analysisToggle').onclick=()=>document.getElementById('analysisBox').classList.toggle('open');document.getElementById('analysisType').onchange=e=>document.getElementById('radiusWrap').style.display=e.target.value==='radius_search'?'block':'none';
map.on('mousemove',e=>document.getElementById('coords').textContent=`${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)}`);map.on('click',async e=>{if(!document.getElementById('analysisBox').classList.contains('open'))return;const type=document.getElementById('analysisType').value,result=document.getElementById('analysisResult');result.innerHTML='<div class="analysis-result">{{ __('Analyzing…') }}</div>';try{const body={_token:CSRF_TOKEN,type,latitude:e.latlng.lat,longitude:e.latlng.lng};if(type==='radius_search')body.radius=Number(document.getElementById('radius').value);const r=await fetch('{{ route('map.analysis') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':CSRF_TOKEN,'Accept':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(type==='radius_search')result.innerHTML=`<div class="analysis-result"><b>${d.stats?.containers_found||0}</b> {{ __('containers') }}<br><b>${d.stats?.dumpsites_found||0}</b> {{ __('dumpsites') }}<br><span class="text-muted">{{ __('Radius') }}: ${d.stats?.radius_km||0} km</span></div>`;else result.innerHTML=`<div class="analysis-result"><b>${esc(d.dumpsite?.properties?.name||'{{ __('Nearest dumpsite') }}')}</b><br>{{ __('Distance') }}: ${d.distance_km??'-'} km</div>`}catch(err){result.innerHTML='<div class="analysis-result text-danger">{{ __('Analysis failed. Try again.') }}</div>'}});
document.getElementById('exportBtn').onclick=()=>{const a=document.createElement('a');a.href='{{ route('map.geojson.export') }}?layer=containers';a.download='containers.geojson';a.click()};load();
</script>@endpush
